from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe')
base='48c1c8dc12abae84a349548f50f64bd48f7691ed'
def git(*args):return subprocess.run(['git',*args],cwd=repo,text=True,capture_output=True,check=True).stdout.strip()
head=git('rev-parse','HEAD');remote=git('rev-parse','origin/main')
print('HEAD',head,'ORIGIN',remote,flush=True)
if head!=base or remote!=base:raise SystemExit('AUTHORITY_CHANGED')
print('DIRTY',repr(git('status','--short')),flush=True)
files=sorted((repo/'tests').glob('test_*.py'))
print('TEST_FILE_COUNT',len(files),flush=True)
if len(files)<120:raise SystemExit('TEST_DISCOVERY_UNEXPECTED')
groups=[files[i::4] for i in range(4)]
passed=skipped=0
for index,group in enumerate(groups,1):
 args=[str(repo/'.venv/bin/python'),'-m','pytest','-q','--tb=short','--maxfail=1']+[str(p.relative_to(repo)) for p in group]
 p=subprocess.Popen(args,cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
 try:o,e=p.communicate(timeout=720)
 except subprocess.TimeoutExpired:
  os.killpg(p.pid,signal.SIGTERM)
  try:o,e=p.communicate(timeout=10)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);o,e=p.communicate()
  print('SHARD_TIMEOUT',index,o[-3000:],e[-600:],flush=True);raise SystemExit(124)
 print('SHARD',index,'FILES',len(group),'EXIT',p.returncode,'TAIL',o[-3400:],'STDERR',e[-800:],flush=True)
 if p.returncode:raise SystemExit('SUITE_REGRESSION_SHARD_'+str(index))
print('FULL_SUITE_VERIFIED_AT',head,flush=True)
print('NO_CODE_CHANGES_NO_PUSH',flush=True)
